<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {eligible,fefo,today,daysFromNow,statusLabels,eventLabels,type StockState,type StockCommand} from '@/services/stockDemo'
const props=defineProps<{tab:string;state:StockState}>()
const emit=defineEmits<{lot:[id:string];product:[id:string];action:[command:StockCommand,id?:string]}>()
const query=ref(''),horizon=ref('90')
watch(()=>props.tab,()=>{query.value='';horizon.value='90'})
const money=(n:number)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'XOF',maximumFractionDigits:0}).format(n)
const product=(id:string)=>props.state.products.find(p=>p.id===id)
const location=(id:string)=>props.state.locations.find(l=>l.id===id)?.name||'—'
const match=(text:string)=>text.toLowerCase().includes(query.value.toLowerCase())
const lots=computed(()=>props.state.lots.filter(l=>match(`${product(l.productId)?.name} ${l.batch} ${location(l.locationId)}`)))
const products=computed(()=>props.state.products.filter(p=>match(p.name+' '+p.code)))
const availableValue=computed(()=>props.state.lots.filter(eligible).reduce((n,l)=>n+l.quantity*l.unitCost,0))
const totalValue=computed(()=>props.state.lots.reduce((n,l)=>n+l.quantity*l.unitCost,0))
const blocked=computed(()=>props.state.lots.filter(l=>l.quantity>0&&!eligible(l)))
const shortage=computed(()=>props.state.products.filter(p=>fefo(props.state,p.id).reduce((n,l)=>n+l.quantity,0)<p.threshold))
const expiring=computed(()=>lots.value.filter(l=>l.quantity>0&&l.expiry<=daysFromNow(Number(horizon.value))).sort((a,b)=>a.expiry.localeCompare(b.expiry)))
const searchedLocations=computed(()=>props.state.locations.filter(l=>match(l.name)))
const occupancy=(id:string)=>props.state.lots.filter(l=>l.locationId===id&&l.quantity>0)
const progress=(n:number,total:number)=>total?Math.min(100,Math.round(n/total*100)):0
const guides:Record<string,{title:string;description:string}>={
 produits:{title:'Catalogue & disponibilité',description:'Une référence produit relie ses lots, son unité et son seuil d’alerte. Les quantités disponibles excluent les lots bloqués.'},
 lots:{title:'Traçabilité par lot et emplacement',description:'Consultez le numéro de lot, sa date et son état avant toute opération. Un même lot peut être réparti sur plusieurs emplacements.'},
 reception:{title:'Contrôler avant de rendre disponible',description:'1 · Saisir le bordereau et le lot   →   2 · Réception en quarantaine   →   3 · Contrôle et levée motivée. Aucun stock disponible automatiquement.'},
 mouvements:{title:'Journal des flux',description:'Réceptions, transferts et corrections sont ajoutés à la suite de l’historique. Une opération validée n’est pas supprimée depuis cette interface.'},
 inventaires:{title:'Poste de comptage',description:'Sélectionnez un lot, comptez la quantité physique puis confirmez l’écart motivé. Le stock attendu est vérifié avant enregistrement.'},
 dechets:{title:'Circuit de sortie des déchets',description:'Préparez une sortie quantifiée et motivée. La sortie du stock ne constitue ni une preuve d’enlèvement ni un certificat de destruction.'}
}
</script>
<template><div class="stock-dashboard" :data-stock-dashboard="tab">
<template v-if="tab==='overview'"><div class="stock-split"><article class="panel stock-pad"><p class="eyebrow">DISPONIBILITÉ</p><h2>Votre stock, en un regard</h2><div class="availability-bar" role="img" :aria-label="'Valeur disponible '+money(availableValue)+' sur '+money(totalValue)"><span :style="{width:progress(availableValue,totalValue)+'%'}"/></div><div class="stock-legend"><span><i class="dot green"/>Disponible {{money(availableValue)}}</span><span><i class="dot amber"/>Bloqué {{money(totalValue-availableValue)}}</span></div><p class="muted">Répartition en valeur brute indicative, pas en nombre d’unités.</p><h3>Priorités de contrôle</h3><div class="priority-line"><span>Références sous leur seuil</span><strong>{{shortage.length}}</strong></div><div class="priority-line"><span>Lignes bloquées avec stock</span><strong>{{blocked.length}}</strong></div><div class="priority-line"><span>Échéance atteinte</span><strong>{{state.lots.filter(l=>l.quantity>0&&l.expiry<=today()).length}}</strong></div></article><article class="panel stock-pad"><p class="eyebrow">ACTIVITÉ RÉCENTE</p><h2>Dernières opérations</h2><ol class="stock-timeline"><li v-for="e in state.events.slice(0,4)" :key="e.id"><strong>{{eventLabels[e.type]}}</strong><p>{{e.reason}}</p><small>{{new Date(e.date).toLocaleString('fr-FR',{timeZone:'Africa/Porto-Novo'})}}</small></li></ol></article></div></template>
<template v-else-if="tab==='fefo'"><div class="panel stock-pad"><div class="stock-section-heading"><div><p class="eyebrow">FILE DE PRIORITÉ · FEFO</p><h2>Le prochain lot, produit par produit</h2><p class="muted">L’échéance la plus proche passe en tête. Indication uniquement : aucune dispensation déclenchée.</p></div><input v-model="query" aria-label="Rechercher un produit FEFO" placeholder="Produit ou code…"/></div><div class="stock-card-grid"><article v-for="p in products" :key="p.id" class="stock-card"><small>{{p.code}}</small><h3>{{p.name}}</h3><ol class="fefo-queue"><li v-for="(l,index) in fefo(state,p.id)" :key="l.id"><span class="rank">{{index+1}}</span><div><strong>{{l.batch}}</strong><p>{{l.expiry}} · {{location(l.locationId)}} · {{l.quantity}} {{p.unit.toLowerCase()}}(s)</p></div><button class="text-link" @click="emit('lot',l.id)">Voir</button></li></ol><p v-if="!fefo(state,p.id).length" class="empty-state">Aucun lot éligible à une sortie.</p></article></div><p v-if="!products.length" class="empty-state">Aucun produit pour cette recherche.</p></div></template>
<template v-else-if="tab==='emplacements'"><div class="stock-section-heading"><div><p class="eyebrow">CARTOGRAPHIE DU STOCK</p><h2>Répartition physique</h2><p class="muted">Les quantités sont connues ; aucune capacité maximale ou occupation volumique n’est supposée.</p></div><input v-model="query" aria-label="Rechercher un emplacement" placeholder="Nom d’emplacement…"/></div><div class="stock-card-grid"><article v-for="l in searchedLocations" :key="l.id" class="panel stock-pad location-card"><span class="location-mark">⌖</span><h2>{{l.name}}</h2><p>{{occupancy(l.id).length}} ligne(s) de lots avec stock</p><strong class="location-quantity">{{occupancy(l.id).reduce((n,x)=>n+x.quantity,0)}} <small>unités physiques</small></strong><p class="muted">{{money(occupancy(l.id).reduce((n,x)=>n+x.quantity*x.unitCost,0))}} · valeur brute</p><div v-for="x in occupancy(l.id)" :key="x.id" class="priority-line"><span>{{x.batch}} <small>{{statusLabels[x.status]}}</small></span><button class="text-link" @click="emit('lot',x.id)">Voir le lot</button></div><p v-if="!occupancy(l.id).length" class="muted">Emplacement sans stock.</p></article></div><p v-if="!searchedLocations.length" class="empty-state">Aucun emplacement trouvé.</p></template>
<template v-else-if="tab==='quarantaine'"><div class="stock-section-heading"><div><p class="eyebrow">ISOLER · CONTRÔLER · TRACER</p><h2>Centre des lots bloqués</h2></div><input v-model="query" aria-label="Rechercher un lot bloqué" placeholder="Produit, lot, emplacement…"/></div><div class="stock-split"><section v-for="status in (['quarantine','recalled'] as const)" :key="status" class="quarantine-column" :class="status"><h2>{{status==='quarantine'?'Contrôles en quarantaine':'Rappels internes simulés'}} <small>{{lots.filter(l=>l.status===status&&l.quantity>0).length}}</small></h2><article v-for="l in lots.filter(l=>l.status===status&&l.quantity>0)" :key="l.id" class="stock-card"><small>{{l.batch}} · {{location(l.locationId)}}</small><h3>{{product(l.productId)?.name}}</h3><p>{{l.quantity}} unités · échéance {{l.expiry}}</p><p v-if="l.expiry<=today()" class="expired-note">Échéance atteinte · levée de quarantaine bloquée</p><button class="button secondary small" @click="emit('lot',l.id)">Examiner le lot</button></article><p v-if="!lots.some(l=>l.status===status&&l.quantity>0)" class="empty-state">Aucun lot dans cette file.</p></section></div></template>
<template v-else-if="tab==='peremptions'"><div class="panel stock-pad"><div class="stock-section-heading"><div><p class="eyebrow">CALENDRIER DES ÉCHÉANCES</p><h2>Anticiper les pertes</h2><p class="muted">Échéance du jour incluse dans les lots bloqués pour cette démonstration.</p></div><label>Horizon<select v-model="horizon" aria-label="Horizon de péremption"><option value="0">Échéance atteinte</option><option value="30">30 jours</option><option value="90">90 jours</option><option value="180">180 jours</option></select></label></div><input v-model="query" aria-label="Rechercher une péremption" placeholder="Produit ou lot…"/><ol class="expiry-timeline"><li v-for="l in expiring" :key="l.id" :class="{expired:l.expiry<=today()}"><time>{{l.expiry}}</time><div><h3>{{product(l.productId)?.name}}</h3><p>{{l.batch}} · {{location(l.locationId)}} · {{l.quantity}} unités</p><small>{{l.expiry<=today()?'Échéance atteinte — bloqué':statusLabels[l.status]}}</small></div><button class="button secondary small" @click="emit('lot',l.id)">Examiner</button></li></ol><p v-if="!expiring.length" class="empty-state">Aucun lot dans cet horizon.</p></div></template>
<template v-else-if="tab==='valorisation'"><div class="stock-split"><article class="panel stock-pad"><p class="eyebrow">RÉPARTITION INDICATIVE</p><h2>Valeur du stock physique</h2><div class="valuation-total">{{money(totalValue)}}</div><div class="availability-bar"><span :style="{width:progress(availableValue,totalValue)+'%'}"/></div><div class="stock-legend"><span>Disponible {{money(availableValue)}}</span><span>Bloqué {{money(totalValue-availableValue)}}</span></div><p class="muted">Valorisation brute au coût de réception, sans dépréciation automatique.</p></article><article class="panel stock-pad"><p class="eyebrow">EXPOSITION AUX BLOCAGES</p><h2>Valeur immobilisée</h2><div v-for="s in (['quarantine','recalled','expired'] as const)" :key="s" class="priority-line"><span>{{s==='expired'?'Échéance atteinte':statusLabels[s]}}</span><strong>{{money(state.lots.filter(l=>s==='expired'?l.expiry<=today():l.expiry>today()&&l.status===s).reduce((n,l)=>n+l.quantity*l.unitCost,0))}}</strong></div><p class="muted">Catégories exclusives : les lots à échéance atteinte sont comptés dans cette catégorie uniquement.</p></article></div></template>
<template v-else-if="guides[tab]"><div class="panel stock-pad workflow-banner"><div><p class="eyebrow">{{tab==='inventaires'?'CONTRÔLE PHYSIQUE':tab==='reception'?'FLUX ENTRANT':tab==='dechets'?'FLUX SORTANT':'ESPACE DE TRAVAIL'}}</p><h2>{{guides[tab].title}}</h2><p class="muted">{{guides[tab].description}}</p></div><div v-if="tab==='inventaires'||tab==='dechets'" class="worklist"><div v-for="l in (tab==='dechets'?blocked:state.lots.filter(l=>l.quantity>0)).slice(0,3)" :key="l.id"><span>{{l.batch}} · {{location(l.locationId)}}</span><button class="button secondary small" @click="emit('action',tab==='inventaires'?'inventory':'waste',l.id)">{{tab==='inventaires'?'Compter ce lot':'Préparer la sortie'}}</button></div></div><div v-if="tab==='reception'" class="receipt-stages"><span>01 · Bordereau</span><span>02 · Quarantaine</span><span>03 · Contrôle</span></div></div></template>
</div></template>
<style scoped>
.stock-dashboard{margin-bottom:20px}.stock-pad{padding:24px}.stock-split{display:grid;grid-template-columns:1.15fr 1fr;gap:20px}.stock-card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(265px,1fr));gap:18px;margin-top:20px}.stock-card{border:1px solid #e2e8f0;border-radius:12px;padding:20px;background:#fff}.stock-dashboard h2{font-size:20px;margin:6px 0 16px}.stock-dashboard h3{font-size:15px;margin:9px 0}.muted,.stock-dashboard small{font-size:12px;color:#64748b;line-height:1.7}.stock-section-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:0 0 18px}.stock-section-heading input{max-width:280px}.stock-dashboard input,.stock-dashboard select{padding:10px 12px;border:1px solid #cbd5e1;border-radius:8px;background:white}.availability-bar{height:14px;border-radius:20px;background:#fde68a;overflow:hidden;margin:26px 0 14px}.availability-bar span{display:block;height:100%;background:#0d9488}.stock-legend{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:#475569;flex-wrap:wrap}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}.green{background:#0d9488}.amber{background:#f59e0b}.priority-line{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:14px 0;border-bottom:1px solid #f1f5f9;font-size:13px}.stock-timeline{padding-left:20px}.stock-timeline li{padding:0 0 16px 12px;border-left:2px solid #e0f2fe}.stock-timeline li::marker{color:#0284c7}.stock-timeline p{font-size:12px;color:#64748b;margin:6px 0}.fefo-queue{list-style:none;padding:0}.fefo-queue li{display:flex;gap:12px;align-items:center;padding:14px 0;border-top:1px solid #f1f5f9}.fefo-queue p{font-size:11px;color:#64748b}.fefo-queue .text-link{margin-left:auto}.rank{background:#e0f2fe;color:#0369a1;border-radius:50%;width:28px;height:28px;display:grid;place-items:center;flex-shrink:0;font-weight:700}.location-mark{display:grid;place-items:center;width:45px;height:45px;border-radius:12px;background:#eff6ff;color:#0369a1;font-size:30px}.location-quantity{font-size:28px;font-family:var(--font-display)}.location-quantity small{font-family:var(--font-sans);font-weight:400}.quarantine-column{padding:20px;border:1px solid #fde68a;border-radius:14px;background:#fffbeb}.quarantine-column.recalled{border-color:#fecaca;background:#fff1f2}.quarantine-column .stock-card{margin-top:14px}.expired-note{color:#b91c1c;font-size:12px}.expiry-timeline{list-style:none;padding:0}.expiry-timeline li{display:flex;align-items:center;gap:20px;padding:20px 0;border-bottom:1px solid #f1f5f9}.expiry-timeline time{padding:10px;border-radius:8px;background:#fffbeb;font-size:13px;color:#92400e;font-weight:700}.expiry-timeline li.expired time{background:#fef2f2;color:#b91c1c}.expiry-timeline li .button{margin-left:auto}.expiry-timeline p{font-size:12px;color:#64748b}.valuation-total{font-family:var(--font-display);font-size:36px;font-weight:700;color:#0f172a}.workflow-banner{border-left:4px solid #0284c7}.receipt-stages{display:flex;gap:16px;margin-top:18px;flex-wrap:wrap}.receipt-stages span{padding:10px 18px;background:#f0f9ff;border-radius:8px;color:#0369a1;font-size:12px;font-weight:600}.worklist{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}.worklist>div{border:1px solid #e2e8f0;padding:12px;border-radius:8px;display:flex;flex-direction:column;gap:12px;font-size:12px}@media(max-width:800px){.stock-split{grid-template-columns:1fr}.stock-section-heading{align-items:flex-start;flex-direction:column}.stock-section-heading input{max-width:100%;width:100%}.expiry-timeline li{flex-wrap:wrap}.stock-pad{padding:18px}.valuation-total{font-size:28px}}
</style>
